CREATE TABLE purchase_order (id BIGINT NOT NULL AUTO_INCREMENT,order_no VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,user_id BIGINT NOT NULL,status VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending_payment',currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,region_code VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,subtotal_minor BIGINT NOT NULL,discount_minor BIGINT NOT NULL DEFAULT 0,total_minor BIGINT NOT NULL,coupon_claim_id BIGINT NULL,idempotency_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_type VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'standard',source_reference VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,payment_expires_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_purchase_order_no UNIQUE(order_no),CONSTRAINT uk_purchase_order_idempotency UNIQUE(user_id,idempotency_key),CONSTRAINT uk_purchase_order_coupon_claim UNIQUE(coupon_claim_id),CONSTRAINT uk_purchase_order_source UNIQUE(source_type,source_reference),KEY idx_purchase_order_owner(user_id,created_at DESC,id DESC),KEY idx_purchase_order_flash_expiry(source_type,status,payment_expires_at,id),CONSTRAINT ck_purchase_order_no CHECK(REGEXP_LIKE(order_no,'^ord_[a-f0-9]{32}$','c')),CONSTRAINT ck_purchase_order_status CHECK(status IN ('pending_payment','paid','cancelled','expired')),CONSTRAINT ck_purchase_order_currency CHECK(REGEXP_LIKE(currency,'^[A-Z]{3}$','c')),CONSTRAINT ck_purchase_order_region CHECK(REGEXP_LIKE(region_code,'^[A-Z0-9-]{2,16}$','c')),CONSTRAINT ck_purchase_order_totals CHECK(subtotal_minor>=0 AND discount_minor>=0 AND discount_minor<=subtotal_minor AND total_minor=subtotal_minor-discount_minor),CONSTRAINT ck_purchase_order_idempotency CHECK(REGEXP_LIKE(idempotency_key,'^[A-Za-z0-9._:-]{8,128}$','c')),CONSTRAINT ck_purchase_order_source CHECK(source_type IN ('standard','flash_sale')),CONSTRAINT ck_purchase_order_source_reference CHECK((source_type='standard' AND source_reference IS NULL AND payment_expires_at IS NULL) OR (source_type='flash_sale' AND source_reference IS NOT NULL AND payment_expires_at IS NOT NULL)),CONSTRAINT ck_purchase_order_flash_reference CHECK(source_reference IS NULL OR REGEXP_LIKE(source_reference,'^fsr_[1-9a-z][0-9a-z]{0,12}_[a-f0-9]{32}$','c')),CONSTRAINT fk_purchase_order_user FOREIGN KEY(user_id) REFERENCES user_account(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
